+      <n-pagination
+        :page="currentPage"
+        :page-count="totalPage"
+        :page-slot="5"
+        @update:page="handlePageChange"
+      />
+    </div>
+  </div>
+</template>
+
+<script setup>
+import { computed, h, ref, watch ,onMounted} from 'vue'
+import { NButton, NDataTable, NInput, NPagination, NSelect } from 'naive-ui'
+import axios from 'axios'
+import { BASE_URL } from '../config'
+
+const emit = defineEmits(['close'])
+
+const currentPage = ref(1)
+const totalPage = ref(1)
+const pageSize = 10
+const tableData = ref([])
+const searchName = ref('')
+
+
+const title ='小流域'
+const columns = [
+  {
+    title: '序号',
+    key: 'index',
+    width: 80,
+    render(_row, rowIndex) {
+      return h('span', {}, (currentPage.value - 1) * pageSize + rowIndex + 1)
+    }
+  },
+  { title: '区县编码', key: 'city', width: 100,  },
+  { title: '隐患点类型', key: 'type', width: 80, },
+  { title: '地理位置', key: 'location', width: 100},
+  { title: '创建时间', key: 'createdTs', width: 100},
+  { title: '最后修改时间	', key: 'lastModifiedTs', width: 100 },
+]
+
+const getQueryParams = () => ({
+  Index: currentPage.value,
+  size:pageSize,
+  // name: searchName.value || undefined
+})
+
+const requestRiskList = async () => {
+  let api = "/api/boot/system/land/landRainXlyImagePage"
+  const res = await axios.get(`${BASE_URL}${api}`, { 
+    params: getQueryParams() 
+  })
+  return getResponsePage(res?.data)
+}
+
+const getResponsePage = data => {
+  const list = data.data.content
+  return {
+    records: Array.isArray(list) ? list : [],
+    pages: Math.ceil(Number(data.data.page.total) / pageSize) 
+  }
+}
+
+const getRiskPointList = async () => {
+  try {
+    const pageData = await requestRiskList()
+    totalPage.value = pageData.pages || 1
+    tableData.value = pageData.records
+  } catch (error) {
+    console.error('获取小流域列表失败:', error)
+    tableData.value = []
+    totalPage.value = 1
+  }
+}
+
+function handleClose() {
+  emit('close')
+}
+
+function handleSearch() {
+  currentPage.value = 1
+  getRiskPointList()
+}
+
+function handleReset() {
+  searchName.value = ''
+  currentPage.value = 1
+  getRiskPointList()
+}
+
+function handlePageChange(page) {
+  currentPage.value = page
+  getRiskPointList()
+}
+
+onMounted(()=>{
+  getRiskPointList()
+})
+
+</script>
+
+<script>
+export default {
+  name: 'Geo‌WaterList'
+}
+</script>
+
+<style lang="scss" scoped>
+@import './geo-table-scroll.scss';
+@font-face {
+  font-family: 'AlibabaPuHuiTi';
+  src: url('../font/Alibaba_PuHuiTi_2.0_55_Regular_55_Regular.ttf') format('truetype');
+  font-weight: normal;
+  font-style: normal;
+}
+
+@font-face {
+  font-family: 'D-DIN';
+  src: url('../font/D-DIN.otf') format('opentype');
+  font-weight: normal;
+  font-style: normal;
+}
+
+.fire-risk-point-modal {
+  font-family: 'AlibabaPuHuiTi', sans-serif;
+  position: absolute;
+  transform: translate(-50%, -50%);
+  z-index: 1001;
+  width: 1300px;
+  height: 600px;
+  display: flex;
+  flex-direction: column;
+  background:
+    url('../img/Group_2136640490.png') top center / 100% 48px no-repeat,
+    linear-gradient(180deg, rgba(3, 19, 54, 0.95) 0%, rgba(2, 12, 36, 0.95) 100%);
+  border: 1px solid rgba(37, 134, 255, 0.25);
+  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.45);
+  color: #b8d9ff;
+  font-size: 14px;
+  overflow: hidden;
+  pointer-events: auto;
+
+  &::before {
+    content: '';
+    position: absolute;
+    inset: 0;
+    background: url('../img/Rectangle_346242153.png') center / cover no-repeat;
+    opacity: 0.25;
+    z-index: -1;
+  }
+}
+
+.modal-header {
+  height: 48px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  position: relative;
+  flex-shrink: 0;
+  padding: 0 32px;
+
+  .header-title {
+    color: #cfe8ff;
+    font-size: 22px;
+    font-weight: 700;
+    text-shadow: 0 0 12px rgba(83, 174, 255, 0.5);
+  }
+
+  .close-btn {
+    position: absolute;
+    right: 20px;
+    top: 50%;
+    transform: translateY(-50%);
+    width: 32px;
+    height: 32px;
+    border: 1px solid rgba(83, 174, 255, 0.3);
+    background: rgba(16, 64, 126, 0.4);
+    color: #aed5ff;
+    font-size: 20px;
+    cursor: pointer;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+
+    &:hover {
+      color: #ffffff;
+      border-color: rgba(83, 174, 255, 0.6);
+      background: rgba(24, 92, 179, 0.6);
+    }
+  }
+}
+
+.query-bar {
+  height: 56px;
+  flex-shrink: 0;
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  padding: 10px 32px 0;
+}
+
+.query-input {
+  width: 240px;
+  background: #0d356b;
+}
+
+.query-select {
+  width: 180px;
+  background: #0d356b;
+}
+
+.query-select :deep(.n-base-selection),
+.query-select :deep(.n-base-selection-label) {
+  background: #0d356b;
+}
+
+
+.query-btn {
+  min-width: 64px;
+  border: 1px solid rgba(83, 174, 255, 0.35);
+  background: rgba(16, 64, 126, 0.45);
+  color: #aed5ff;
+}
+
+.modal-content {
+  flex: 1;
+  min-height: 0;
+  display: flex;
+  padding: 12px 32px 8px;
+  overflow: hidden;
+}
+
+:deep(.fire-table) {
+  flex: 1;
+  height: 100%;
+  min-height: 0;
+
+  .n-data-table-wrapper {
+    background: transparent;
+  }
+
+  .n-data-table-table {
+    background: transparent;
+    font-size: 14px;
+  }
+
+  .n-data-table-th {
+    height: 40px;
+    padding: 0 12px;
+    color: #8bbce6;
+    font-weight: 500;
+    background: #0b437c;
+    border: none;
+  }
+
+  .n-data-table-td {
+    height: 40px;
+    padding: 0 12px;
+    color: #d7e9ff;
+    font-family: 'D-DIN', 'AlibabaPuHuiTi', sans-serif;
+    background: #0a325f;
+    border: none;
+  }
+
+  .n-data-table-tr:nth-child(even) .n-data-table-td {
+    background: #19406b;
+  }
+
+  .n-data-table-tr:hover .n-data-table-td {
+    background: rgba(29, 107, 202, 0.3);
+  }
+}
+
+.modal-footer {
+  height: 60px;
+  flex-shrink: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 0 32px;
+
+  :deep(.n-pagination) {
+    display: flex;
+    align-items: center;
+    gap: 6px;
+  }
+
+  :deep(.n-pagination-item),
+  :deep(.n-pagination-button) {
+    min-width: 32px;
+    height: 32px;
+    border: 1px solid rgba(83, 174, 255, 0.35);
+    background: rgba(16, 64, 126, 0.4);
+    color: #aed5ff;
+    font-size: 14px;
+    border-radius: 2px;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    cursor: pointer;
+  }
+
+  :deep(.n-pagination-item:hover),
+  :deep(.n-pagination-button:hover) {
+    color: #ffffff;
+    border-color: rgba(83, 174, 255, 0.6);
+    background: rgba(24, 92, 179, 0.6);
+  }
+
+  :deep(.n-pagination-item--active) {
+    background: rgba(37, 134, 255, 0.8) !important;
+    border-color: rgba(37, 134, 255, 0.9) !important;
+    color: #ffffff !important;
+  }
+}
+</style>

